/**
 * Generated by quail.
 *
 * Responsive smoke for https://www.spritecloud.com/functional-testing. Visits the page at mobile (375px),
 * tablet (768px), and desktop (1280px) viewports and asserts the page
 * still renders a visible h1. Catches catastrophic responsive
 * breakdowns without taking screenshots.
 *
 * Filter: `npx playwright test --grep @kind:responsive`
 */
import { test } from '@playwright/test'
import { VIEWPORTS, mobileNav, assertHeadingVisible, assertBodyHasText } from '../prims'

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — responsive @ https://www.spritecloud.com/functional-testing', () => {
  for (const vp of VIEWPORTS) {
    test(`@kind:responsive @smoke renders at ${vp.name} (${vp.width}x${vp.height})`, async ({ page }) => {
      await page.setViewportSize({ width: vp.width, height: vp.height })
      await mobileNav(page, 'https://www.spritecloud.com/functional-testing')
      await assertHeadingVisible(page)
      await assertBodyHasText(page)
    })
  }
})
